import raw from './generated/catalog.json';
import type { Area, AreaId, Catalog, TCode } from '../types.ts';
import { CURATED_CODES } from './codes-curated.ts';

/** The parsed almanac (393 codes, 18 areas), generated by `npm run data:build`. */
export const catalog = raw as Catalog;

export const AREAS: readonly Area[] = catalog.areas;
/** The almanac's own codes, in almanac order. */
export const ALMANAC_CODES: readonly TCode[] = catalog.codes;
export { CURATED_CODES };
/** Message variables {almanac} and {curated} for texts that state the catalog size. */
export const CODE_COUNTS = { almanac: ALMANAC_CODES.length, curated: CURATED_CODES.length } as const;

/**
 * Every code T-Coder knows: per area, the almanac's codes first, then the
 * curated ones. Search breaks ties in this order, so almanac codes lead.
 */
export const CODES: readonly TCode[] = AREAS.flatMap((a) => [
  ...ALMANAC_CODES.filter((c) => c.area === a.id),
  ...CURATED_CODES.filter((c) => c.area === a.id),
]);

const byCode = new Map(CODES.map((c) => [c.code, c]));
const byArea = new Map<AreaId, TCode[]>();
for (const c of CODES) {
  const list = byArea.get(c.area) ?? [];
  list.push(c);
  byArea.set(c.area, list);
}
const curated = new Set(CURATED_CODES.map((c) => c.code));

export const getCode = (code: string): TCode | undefined => byCode.get(code);
export const hasCode = (code: string): boolean => byCode.has(code);
/** True for codes added for T-Coder, false for almanac codes (and unknown ones). */
export const isCurated = (code: string): boolean => curated.has(code);
export const getArea = (id: AreaId): Area | undefined => AREAS.find((a) => a.id === id);
export const codesInArea = (id: AreaId): readonly TCode[] => byArea.get(id) ?? [];

/** Case-insensitive lookup by exact code. */
export const lookupCode = (input: string): TCode | undefined => byCode.get(input.trim().toUpperCase());
